package cn.mop.adapters.backup;

import cn.mop.domain.DomainException;
import cn.mop.adapters.backup.RedactedBackupDiff.*;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import static org.junit.jupiter.api.Assertions.*;

/** Real pinned diff library, synthetic bytes only; no device, storage, HTTP or backup fixture service. */
class RedactedBackupDiffTest {
    final UUID tenant=UUID.fromString("55000000-0000-4000-8000-000000000001"),asset=UUID.fromString("66000000-0000-4000-8000-000000000001");
    VersionInput input(String value){return new VersionInput(tenant,asset,UUID.randomUUID(),value.getBytes(StandardCharsets.UTF_8));}
    Summary compare(String before,String after){return new RedactedBackupDiff().compare(tenant,asset,input(before),input(after));}
    @Test void sameBytesDoNotCreateDifferences(){var r=compare("hostname 路由器\ninterface e0\n","hostname 路由器\ninterface e0\n");assertEquals(Status.IDENTICAL,r.status());assertEquals(false,r.changed());assertEquals(2,r.beforeLines());assertTrue(r.hunks().isEmpty());assertFalse(r.changeApproved());}
    @Test void emptyConfigurationsRemainZeroLines(){var r=compare("","");assertEquals(Status.IDENTICAL,r.status());assertEquals(0,r.beforeLines());assertEquals(0,r.afterLines());}
    @Test void insertionAndDeletionExposeOnlyPositionsAndCounts(){var inserted=compare("a\nb\n","a\nx\nb\n");assertEquals(Status.CHANGED,inserted.status());assertEquals(1,inserted.hunks().stream().mapToInt(Hunk::afterCount).sum());assertEquals(0,inserted.hunks().stream().mapToInt(Hunk::beforeCount).sum());var removed=compare("a\nx\nb\n","a\nb\n");assertEquals(1,removed.hunks().stream().mapToInt(Hunk::beforeCount).sum());assertEquals(0,removed.hunks().stream().mapToInt(Hunk::afterCount).sum());}
    @Test void sensitiveHtmlAndCommandChangesNeverAppearInResult(){String a="password SYNTHETIC_SECRET_OLD\n<script>alert('x')</script>\n",b="password SYNTHETIC_SECRET_NEW\n<script>alert('y')</script>\n";var left=input(a);var r=new RedactedBackupDiff().compare(tenant,asset,left,input(b));assertEquals(Status.CHANGED,r.status());assertEquals("ALL_TEXT_WITHHELD",r.redaction());for(String forbidden:List.of("SYNTHETIC","password","script","alert")){assertFalse(r.toString().contains(forbidden));assertFalse(left.toString().contains(forbidden));}}
    @Test void allTextMaskingCannotHideChangesToSecretValues(){assertEquals(Status.CHANGED,compare("secret aaa\n","secret bbb\n").status());assertEquals(Status.IDENTICAL,compare("secret aaa\n","secret aaa\n").status());}
    @Test void whitespaceLineEndingsAndFinalNewlineAreNotSilentlyNormalized(){for(List<String> pair:List.of(List.of("a\n","a"),List.of("a\r\n","a\n"),List.of(" a\n","a\n"),List.of("a\r","a\n"),List.of("a\n","a\n\n"))){var r=compare(pair.get(0),pair.get(1));assertEquals(Status.CHANGED,r.status());assertFalse(r.normalized());assertEquals("NONE_APPLIED_UNCONFIRMED",r.noisePolicy());}}
    @Test void unapprovedDynamicNoiseRemainsARealDifference(){assertEquals(Status.CHANGED,compare("generated 12:00\n","generated 12:01\n").status());}
    @Test void tenantAndAssetScopeCheckedBeforeParsingEitherBody(){var broken=new byte[]{(byte)0xc3,(byte)0x28};for(VersionInput wrong:List.of(new VersionInput(UUID.randomUUID(),asset,UUID.randomUUID(),broken),new VersionInput(tenant,UUID.randomUUID(),UUID.randomUUID(),broken))){assertEquals(404,assertThrows(DomainException.class,()->new RedactedBackupDiff().compare(tenant,asset,input("a"),wrong)).status);assertEquals(404,assertThrows(DomainException.class,()->new RedactedBackupDiff().compare(tenant,asset,wrong,input("a"))).status);}}
    @Test void immutableVersionIdentityCannotReferToDifferentBytes(){UUID id=UUID.randomUUID();var a=new VersionInput(tenant,asset,id,new byte[]{65});var b=new VersionInput(tenant,asset,id,new byte[]{66});assertEquals(409,assertThrows(DomainException.class,()->new RedactedBackupDiff().compare(tenant,asset,a,b)).status);assertEquals(Status.IDENTICAL,new RedactedBackupDiff().compare(tenant,asset,a,a).status());}
    @Test void invalidUtf8AndBinaryNullFailWithoutEchoingPayload(){for(byte[] bytes:List.of(new byte[]{(byte)0xc3,(byte)0x28},new byte[]{0},new byte[]{(byte)0xed,(byte)0xa0,(byte)0x80})){var r=new VersionInput(tenant,asset,UUID.randomUUID(),bytes);assertThrows(DomainException.class,()->new RedactedBackupDiff().compare(tenant,asset,r,input("")));}}
    @Test void inputByteLimitIsCheckedBeforeCopy(){assertThrows(DomainException.class,()->new VersionInput(tenant,asset,UUID.randomUUID(),new byte[RedactedBackupDiff.MAX_BYTES+1]));}
    @Test void inputIsDefensivelyCopied(){byte[] bytes="a\n".getBytes(StandardCharsets.UTF_8);var a=new VersionInput(tenant,asset,UUID.randomUUID(),bytes);bytes[0]='b';assertEquals(Status.IDENTICAL,new RedactedBackupDiff().compare(tenant,asset,a,input("a\n")).status());}
    @Test void exactLineLimitPassesButOverflowIsUnknownNotUnchanged(){assertEquals(Status.IDENTICAL,compare("x\n".repeat(1000),"x\n".repeat(1000)).status());var r=compare("x\n".repeat(1001),"");assertEquals(Status.LIMIT_EXCEEDED,r.status());assertNull(r.changed());assertNull(r.beforeLines());assertTrue(r.hunks().isEmpty());}
    @Test void lineByteLimitCountsUtf8RatherThanCharacters(){assertEquals(Status.IDENTICAL,compare("中".repeat(2730),"中".repeat(2730)).status());assertEquals(Status.LIMIT_EXCEEDED,compare("中".repeat(2731),"").status());}
    @Test void comparisonWorkBudgetStopsRealLibraryWithoutPartialOutput(){var diff=new RedactedBackupDiff(()->0L,100,1);var r=diff.compare(tenant,asset,input("a\nb\nc"),input("x\ny\nz"));assertEquals(Status.LIMIT_EXCEEDED,r.status());assertNull(r.changed());assertTrue(r.hunks().isEmpty());}
    @Test void elapsedBudgetUsesInjectableMonotonicClockWithoutSleeping(){AtomicLong clock=new AtomicLong();var r=new RedactedBackupDiff(clock::getAndIncrement,1,100).compare(tenant,asset,input("a"),input("b"));assertEquals(Status.LIMIT_EXCEEDED,r.status());assertNull(r.changed());}
    @Test void interruptionPreservedAndDoesNotProduceFalseIdentical(){try{Thread.currentThread().interrupt();var r=compare("a","a");assertEquals(Status.CANCELLED,r.status());assertNull(r.changed());assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
    @Test void returnedHunksAreImmutableAndNeverAuthorizeTicketOrApproval(){var r=compare("a","b");assertThrows(UnsupportedOperationException.class,()->r.hunks().clear());assertFalse(r.changeApproved());assertFalse(r.automaticTicketAllowed());}
    @Test void invalidSummaryCannotClaimUnchangedWithMismatchedLineCounts(){assertThrows(DomainException.class,()->new Summary(Status.IDENTICAL,1,2,List.of()));assertThrows(DomainException.class,()->new Summary(Status.LIMIT_EXCEEDED,1,1,List.of()));assertThrows(DomainException.class,()->new Summary(Status.CHANGED,1,1,List.of()));}
    @Test void overflowedOrOverlargeHunkCoordinatesCannotPassBounds(){assertThrows(DomainException.class,()->new Hunk(Integer.MAX_VALUE,1,0,0));assertThrows(DomainException.class,()->new Hunk(0,Integer.MAX_VALUE,0,1));assertThrows(DomainException.class,()->new Hunk(1001,0,0,1));}
    @Test void deterministicSmallCorpusMatchesExactByteEqualityAndBalancedLineCounts(){Random random=new Random(20261003);for(int sample=0;sample<200;sample++){StringBuilder a=new StringBuilder(),b=new StringBuilder();for(int i=0;i<random.nextInt(15);i++)a.append((char)('a'+random.nextInt(4))).append('\n');for(int i=0;i<random.nextInt(15);i++)b.append((char)('a'+random.nextInt(4))).append('\n');var r=compare(a.toString(),b.toString());assertEquals(a.toString().equals(b.toString())?Status.IDENTICAL:Status.CHANGED,r.status());int removed=r.hunks().stream().mapToInt(Hunk::beforeCount).sum(),added=r.hunks().stream().mapToInt(Hunk::afterCount).sum();assertEquals(r.afterLines(),r.beforeLines()-removed+added);}}
}
